// Independent coefficient-pair field arithmetic, linear Miller chain and linear field DLP reference.
use std::{collections::BTreeSet,fmt::Write as _,fs,io::Write};
use sha2::{Digest,Sha256};use serde_json::{Value,json};use std::path::Path;
fn digest(s:&[u8])->String{format!("{:x}",Sha256::digest(s))}
type F=(i64,i64);type P=Option<(F,F)>;fn md(x:i64)->i64{x.rem_euclid(61)}fn addf(x:F,y:F)->F{(md(x.0+y.0),md(x.1+y.1))}fn nf(x:F)->F{(md(-x.0),md(-x.1))}fn subf(x:F,y:F)->F{addf(x,nf(y))}static BASE_POLY:std::sync::atomic::AtomicBool=std::sync::atomic::AtomicBool::new(false);
struct BaseScope(bool);impl BaseScope{fn new(b:bool)->Self{Self(BASE_POLY.swap(b,std::sync::atomic::Ordering::Relaxed))}}impl Drop for BaseScope{fn drop(&mut self){BASE_POLY.store(self.0,std::sync::atomic::Ordering::Relaxed);}}
fn mf(x:F,y:F)->F{if BASE_POLY.load(std::sync::atomic::Ordering::Relaxed){assert_eq!(x.1,0);assert_eq!(y.1,0);return(md(x.0*y.0),0)}(md(x.0*y.0+59*x.1*y.1),md(x.0*y.1+x.1*y.0))}fn pow(mut x:F,mut n:i64)->F{let mut r=(1,0);while n>0{if n%2==1{r=mf(r,x)}x=mf(x,x);n/=2;}r}fn div(x:F,y:F)->F{assert_ne!(y,(0,0));if BASE_POLY.load(std::sync::atomic::Ordering::Relaxed){assert_eq!(x.1,0);assert_eq!(y.1,0);return mf(x,pow(y,59))}mf(x,pow(y,3719))}fn enc(x:F)->i64{x.0+61*x.1}
fn neg(p:P)->P{p.map(|(x,y)|(x,nf(y)))}fn on(p:P,a:i64,b:i64)->bool{p.is_none_or(|(x,y)|mf(y,y)==addf(addf(mf(mf(x,x),x),mf((a,0),x)),(b,0)))}
fn plus(p:P,q:P,a:i64)->P{let((x,y),(u,v))=match(p,q){(None,q)=>return q,(p,None)=>return p,(Some(p),Some(q))=>(p,q)};if x==u&&addf(y,v)==(0,0){return None}let m=if x==u{div(addf(mf((3,0),mf(x,x)),(a,0)),mf((2,0),y))}else{div(subf(v,y),subf(u,x))};let z=subf(subf(mf(m,m),x),u);let c=subf(y,mf(m,x));Some((z,nf(addf(mf(m,z),c))))}
fn mul(p:P,n:i64,a:i64)->P{let mut r=None;for _ in 0..n{r=plus(r,p,a)}r}fn chi(p:P)->P{p.map(|(x,y)|(div(x,(59,0)),div(y,(0,59))))}
fn line(p:P,q:P,at:P)->Option<F>{let((x,y),(u,v),(xx,yy))=(p?,q?,at?);if x==u&&addf(y,v)==(0,0){let z=subf(xx,x);return(z!=(0,0)).then_some(z)}let den=if x==u{mf((2,0),y)}else{subf(u,x)};if den==(0,0){return None}let m=if x==u{div(addf(mf((3,0),mf(x,x)),(21,0)),den)}else{div(subf(v,y),den)};let num=subf(subf(yy,y),mf(m,subf(xx,x)));let vert=plus(p,q,21).map_or((1,0),|(z,_)|subf(xx,z));(num!=(0,0)&&vert!=(0,0)).then(||div(num,vert))}
fn miller(p:P,at:P)->Option<F>{p?;at?;let mut r=p;let mut f=(1,0);for _ in 1..31{f=mf(f,line(r,p,at)?);r=plus(r,p,21)}assert_eq!(r,None);Some(f)}fn weil(p:P,q:P)->Option<F>{if p.is_none()||q.is_none(){return Some((1,0))}Some(nf(div(miller(p,q)?,miller(q,p)?)))}fn shifted(p:P,q:P,s:P)->Option<F>{if p.is_none()||q.is_none(){return Some((1,0))}Some(mf(div(miller(p,plus(q,s,21))?,miller(p,s)?),div(miller(q,neg(s))?,miller(q,plus(p,neg(s),21))?)))}
fn group(g:P,a:i64,b:i64)->Vec<P>{let mut set=BTreeSet::new();let mut p=None;for _ in 0..31{assert!(set.insert(p));assert!(on(p,a,b));p=plus(p,g,a);}assert_eq!(p,None);set.into_iter().collect()}
fn point(p:P)->String{match p{None=>"-1 -1".to_string(),Some((x,y))=>format!("{} {}",enc(x),enc(y))}}
fn solve(g:F,value:F)->i64{assert_ne!(g,(1,0));assert_eq!(pow(g,31),(1,0));let mut p=(1,0);for n in 0..31{if p==value{return n}p=mf(p,g);}panic!("finite field log absent")}
type Poly=Vec<F>;fn trim(a:&mut Poly){while a.last()==Some(&(0,0)){a.pop();}}fn degree(a:&Poly)->i32{a.len()as i32-1}fn scale(mut a:Poly,b:F)->Poly{for x in &mut a{*x=mf(*x,b)}trim(&mut a);a}fn sub(mut a:Poly,b:&Poly)->Poly{a.resize(a.len().max(b.len()),(0,0));for(i,&x)in b.iter().enumerate(){a[i]=subf(a[i],x)}trim(&mut a);a}
fn bound(n:i32,cap:i32,peak:&mut i32)->Result<(),()>{if n>cap{return Err(())}*peak=(*peak).max(n);Ok(())}
fn product(a:&Poly,b:&Poly,cap:i32,weight:i32,peak:&mut i32)->Result<Poly,()>{if a.is_empty()||b.is_empty(){return Ok(vec![])}bound(degree(a)+degree(b)+weight,cap,peak)?;let mut c=vec![(0,0);a.len()+b.len()-1];for(i,&x)in a.iter().enumerate(){for(j,&y)in b.iter().enumerate(){c[i+j]=addf(c[i+j],mf(x,y))}}trim(&mut c);Ok(c)}
fn divide(mut a:Poly,b:&Poly,cap:i32,peak:&mut i32)->Result<(Poly,Poly),()>{assert!(!b.is_empty());let mut q=vec![(0,0);(degree(&a)-degree(b)+1).max(0)as usize];while !a.is_empty()&&degree(&a)>=degree(b){let k=(degree(&a)-degree(b))as usize;let v=div(*a.last().unwrap(),*b.last().unwrap());q[k]=addf(q[k],v);let mut mono=vec![(0,0);k+1];mono[k]=v;a=sub(a,&product(&mono,b,cap,0,peak)?);}trim(&mut q);Ok((q,a))}
static TERMINAL_STOP:std::sync::atomic::AtomicBool=std::sync::atomic::AtomicBool::new(false);
fn certificate(a:&[F],b:&[F],z:F,cap:i32,peak:&mut i32)->Result<(Poly,Poly,Poly,Poly,Poly),()>{assert_eq!(pow(z,31),(1,0));assert_ne!(z.0,60);let route=ROUTE.load(std::sync::atomic::Ordering::Relaxed);let _mode=BaseScope::new(route==4);bound(3,cap,peak)?;let mut f=vec![(1,0)];let mut h=f.clone();
if route==4{for &(aa,bb) in a{assert_ne!(aa,60);assert_eq!(md(aa*aa-59*bb*bb),1);f=product(&f,&vec![(md(-bb),0),(md(aa+1),0)],cap,0,peak)?;}for &(aa,bb) in b{assert_ne!(aa,60);assert_eq!(md(aa*aa-59*bb*bb),1);h=product(&h,&vec![(md((aa+1)*z.1-bb*(z.0+1)),0),(md(-(aa+1)*(z.0+1)+59*bb*z.1),0)],cap,0,peak)?;}}
else{for &x in a{f=product(&f,&vec![nf(x),(1,0)],cap,0,peak)?;}for &x in b{h=product(&h,&vec![z,nf(x)],cap,0,peak)?;}}
let(mut r0,mut r1)=(f.clone(),h.clone());let(mut u0,mut u1,mut v0,mut v1)=(vec![(1,0)],vec![],vec![],vec![(1,0)]);while !r1.is_empty(){let(q,r)=divide(r0,&r1,cap,peak)?;if TERMINAL_STOP.load(std::sync::atomic::Ordering::Relaxed)&&r.is_empty(){r0=r1;u0=u1;v0=v1;break;}let u=sub(u0,&product(&q,&u1,cap,3,peak)?);let v=sub(v0,&product(&q,&v1,cap,3,peak)?);r0=r1;r1=r;u0=u1;u1=u;v0=v1;v1=v;}let k=div((1,0),*r0.last().unwrap());r0=scale(r0,k);u0=scale(u0,k);v0=scale(v0,k);let uf=product(&u0,&f,cap,0,peak)?;let vh=product(&v0,&h,cap,0,peak)?;assert!(sub(sub(uf,&scale(vh,(-1,0))),&r0).is_empty());assert!(divide(f.clone(),&r0,cap,peak)?.1.is_empty()&&divide(h.clone(),&r0,cap,peak)?.1.is_empty());Ok((f,h,r0,u0,v0))}
fn root(a:&Poly,x:F)->bool{let _mode=BaseScope::new(true);let(mut value,mut den)=((0,0),(1,0));for &c in a.iter().rev(){value=addf(mf(value,(x.1,0)),mf(c,den));den=mf(den,(md(x.0+1),0));}value==(0,0)}
fn eval(a:&Poly,x:F)->F{a.iter().rev().fold((0,0),|z,&c|addf(mf(z,x),c))}fn poly(a:&Poly)->String{let mut z=a.len().to_string();for &x in a{write!(z,",{}",enc(x)).unwrap()}z}
fn rel(x:i64)->i64{x.rem_euclid(31)}fn rinv(x:i64)->i64{(1..31).find(|&y|rel(x*y)==1).unwrap()}
fn insert(matrix:&mut std::collections::BTreeMap<usize,[i64;4]>,row:[i64;3],m:i64){let mut r=[rel(row[0]),rel(row[1]),rel(row[2]),rel(m)];for(&p,b)in matrix.iter(){let c=r[p];for j in 0..4{r[j]=rel(r[j]-c*b[j]);}}let p=(0..3).find(|&j|r[j]!=0);let Some(p)=p else{assert_eq!(r[3],0);return};let k=rinv(r[p]);for x in &mut r{*x=rel(*x*k)}for b in matrix.values_mut(){let c=b[p];for j in 0..4{b[j]=rel(b[j]-c*r[j]);}}matrix.insert(p,r);}
fn query_cold(q:P,s:P,base:&[P],images:&[F],cap:i32,count:&mut[i64;11],trace:&mut String,supplied:Option<F>)->Vec<[i64;3]>{let z=if cap>=3{if supplied.is_none(){count[1]+=1;}supplied.unwrap_or_else(||pair(q,s).unwrap())}else{(0,0)};writeln!(trace,"QUERY {} {}",point(q),enc(z)).unwrap();let mut rows=vec![];for sign in [-1,1]{for sign2 in [-1,1]{count[2]+=1;let mut peak=0;write!(trace,"BR {} {} ",sign,sign2).unwrap();let result=if cap<3{Err(())}else{let a:Vec<_>=images.iter().map(|&x|if sign==1{x}else{if ROUTE.load(std::sync::atomic::Ordering::Relaxed)>=4{(x.0,md(-x.1))}else{div((1,0),x)}}).collect();let b:Vec<_>=images.iter().map(|&x|if sign2==1{x}else{if ROUTE.load(std::sync::atomic::Ordering::Relaxed)>=4{(x.0,md(-x.1))}else{div((1,0),x)}}).collect();certificate(&a,&b,z,cap,&mut peak).map(|c|(a,b,c))};match result{Ok((a,b,(f,h,d,u,v)))=>{let mut found=vec![];for i in 0..3{count[5]+=1;if if ROUTE.load(std::sync::atomic::Ordering::Relaxed)==4{root(&d,a[i])}else{eval(&d,a[i])==(0,0)}{for j in 0..3{if mf(a[i],b[j])==z{assert_eq!(plus(if sign==1{base[i]}else{neg(base[i])},if sign2==1{base[j]}else{neg(base[j])},21),q);let mut row=[0;3];row[i]+=sign;row[j]+=sign2;rows.push(row);found.push((i,j));}}}}let mut reference=vec![];for i in 0..3{for j in 0..3{if plus(if sign==1{base[i]}else{neg(base[i])},if sign2==1{base[j]}else{neg(base[j])},21)==q{reference.push((i,j));}}}assert_eq!(found,reference,"complete actual signed source-row coverage after certificate");write!(trace,"C {} {} {} {} {} {} {}",peak,poly(&f),poly(&h),poly(&d),poly(&u),poly(&v),found.len()).unwrap();for(i,j)in &found{write!(trace," {},{}",i,j).unwrap()}trace.push('\n');count[4]+=1;count[6]+=found.len()as i64;},Err(())=>{writeln!(trace,"U {}",peak).unwrap();count[3]+=1;}}count[9]=count[9].max(peak as i64);}}rows}
struct Recovery{scalar:i64,kind:i64,rank:usize,setup_m:i64,shift:i64,logs:[i64;3],count:[i64;11],trace:String}

static ROUTE:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
fn pair(p:P,q:P)->Option<F>{if ROUTE.load(std::sync::atomic::Ordering::Relaxed)<2{return weil(p,q)}if p.is_none()||q.is_none(){return Some((1,0))}Some(pow(miller(p,q)?,120))}
fn recover_cold(unknown:P,g:P,s:P,base:&[P],cap:i32)->Recovery{let route=ROUTE.load(std::sync::atomic::Ordering::Relaxed);let mut r=Recovery{scalar:-1,kind:0,rank:0,setup_m:0,shift:-1,logs:[-1;3],count:[0;11],trace:String::new()};let mut images=vec![];for &p in base{let v=pair(p,s).unwrap();assert_ne!(v,(1,0));images.push(v);r.count[0]+=1;}let zeta=if route>=3{r.count[1]+=1;let z=pair(g,s).unwrap();assert_ne!(z,(1,0));assert_eq!(pow(z,31),(1,0));z}else{(1,0)};let mut public_image=(1,0);let mut matrix=std::collections::BTreeMap::new();let mut setup=None;
for m in 1..=30{if matrix.len()==3{break}setup=plus(setup,g,21);r.count[7]+=1;writeln!(r.trace,"PUBLIC {}",m).unwrap();let supplied=if route>=3{public_image=mf(public_image,zeta);r.count[10]+=1;Some(public_image)}else{None};let rows=query_cold(setup,s,base,&images,cap,&mut r.count,&mut r.trace,supplied);for row in rows{insert(&mut matrix,row,m)}r.setup_m=m;}
r.rank=matrix.len();if r.rank!=3{return r}r.logs=[matrix[&0][3],matrix[&1][3],matrix[&2][3]];for i in 0..3{assert_eq!(mul(g,r.logs[i],21),base[i]);}let mut image=if route>=3{r.count[1]+=1;pair(unknown,s).unwrap()}else{(1,0)};let mut shifted=unknown;
for shift in 0..=30{r.count[8]+=1;writeln!(r.trace,"ONLINE {}",shift).unwrap();if shifted.is_none(){r.scalar=rel(-shift);r.kind=2;r.shift=shift;r.trace.push_str("IDENTITY\n");break}let rows=query_cold(shifted,s,base,&images,cap,&mut r.count,&mut r.trace,if route>=3{Some(image)}else{None});if !rows.is_empty(){r.scalar=rel((0..3).map(|i|rows[0][i]*r.logs[i]).sum::<i64>()-shift);r.kind=1;r.shift=shift;break}shifted=plus(shifted,g,21);if route>=3{image=mf(image,zeta);r.count[10]+=1;}}
assert!(r.scalar>=0);assert_eq!(mul(g,r.scalar,21),unknown);r}
fn result(r:&Recovery)->Value{json!({"scalar":r.scalar,"kind":r.kind,"rank":r.rank,"setup_m":r.setup_m,"shift":r.shift,"logs":r.logs,"counts":r.count})}
fn profile(route:usize,policy:usize,cap:i32,g:P,s:P,source:&[P],base:&[P])->(String,Value){ROUTE.store(route,std::sync::atomic::Ordering::Relaxed);TERMINAL_STOP.store(route!=0,std::sync::atomic::Ordering::Relaxed);let mut out=format!("PROJECTIVE {} {} {} 61 59 31\nBASE",route,policy,cap);for &p in base{write!(out," {}",point(p)).unwrap()}out.push('\n');let mut count=[0i64;11];let images:Vec<_>=base.iter().map(|&b|pair(b,s).unwrap()).collect();let mut ranks=vec![];let mut rank_sum=0;
for(qi,&q)in source.iter().enumerate(){writeln!(out,"DIAG {}",qi).unwrap();let rows=query_cold(q,s,base,&images,cap,&mut count,&mut out,None);let mut m=std::collections::BTreeMap::new();for row in rows{insert(&mut m,row,0)}ranks.push(m.len());if qi!=0{rank_sum+=m.len();}writeln!(out,"RANK {}",m.len()).unwrap();}
let mut works=vec![];for(qi,&q)in source.iter().enumerate().skip(1){let r=recover_cold(q,g,s,base,cap);write!(out,"WORK {} {} {} {} {} {}",qi,r.scalar,r.kind,r.rank,r.setup_m,r.shift).unwrap();for x in r.logs{write!(out," {}",x).unwrap()}for x in r.count{write!(out," {}",x).unwrap()}writeln!(out,"\n{}END",r.trace).unwrap();works.push(json!({"target":qi,"result":result(&r)}));}
(out,json!({"route":route,"policy":policy,"cap":cap,"diagnostic_ranks":ranks,"rank_numerator":rank_sum,"works":works,"matrix_degree":null,"polynomial_field":if route==4{"F61"}else{"F61^2"},"original_input_pullback_witness_degree":null}))}
fn stripped(v:&Value)->Value{let mut s=v.clone();for w in s["works"].as_array_mut().unwrap(){w.as_object_mut().unwrap().remove("timings");}s}
#[link(name="z")] extern "C"{fn gzopen(path:*const std::ffi::c_char,mode:*const std::ffi::c_char)->*mut std::ffi::c_void;fn gzread(file:*mut std::ffi::c_void,buf:*mut std::ffi::c_void,len:u32)->i32;fn gzclose(file:*mut std::ffi::c_void)->i32;}
fn read_gz(path:&Path)->Vec<u8>{let p=std::ffi::CString::new(path.to_str().unwrap()).unwrap();unsafe{let f=gzopen(p.as_ptr(),c"rb".as_ptr());assert!(!f.is_null());let mut out=vec![];loop{let mut b=[0u8;65536];let n=gzread(f,b.as_mut_ptr().cast(),b.len()as u32);assert!(n>=0);if n==0{break}out.extend_from_slice(&b[..n as usize]);}assert_eq!(gzclose(f),0);out}}
fn audit(cpath:&Path,apath:&Path,bpath:&Path)->Value{let read=|p:&Path|->Value{serde_json::from_slice(&read_gz(&p.join("index.json.gz"))).unwrap()};let c=read(cpath);let a=read(apath);let b=read(bpath);for(v,tag)in[(&c,"C"),(&a,"A"),(&b,"B")]{assert_eq!(v["schema"],"twist.projective-cold/v1");assert_eq!(v["tag"],tag);assert_eq!(v["cases"].as_array().unwrap().len(),2730);}
assert!((0..61).all(|x|md(x*x)!=59),"actual nonsquare extension parameter");let g=Some(((0,0),(10,0)));let s=chi(Some(((37,0),(14,0))));assert!(on(g,21,39)&&on(s,21,39)&&mul(g,31,21).is_none()&&mul(s,31,21).is_none());assert_eq!(s.map(|(x,y)|(pow(x,61),pow(y,61))),neg(s));let source=group(g,21,39);let reps:Vec<_>=source.iter().copied().filter(|q|q.is_some()&&q<&neg(*q)).collect();assert_eq!(reps.len(),15);let mut maps=vec![];for route in 3..6{ROUTE.store(route,std::sync::atomic::Ordering::Relaxed);let z=pair(g,s).unwrap();assert_ne!(z,(1,0));assert_eq!(pow(z,31),(1,0));for &q in &source{let v=pair(q,s).unwrap();assert_eq!(pow(v,31),(1,0));let(x,y)=q.map_or((-1,-1),|(x,y)|(enc(x),enc(y)));maps.push(json!([route,x,y,enc(v)]));}for &x in &source{for &y in &source{assert_eq!(pair(plus(x,y,21),s).unwrap(),mf(pair(x,s).unwrap(),pair(y,s).unwrap()));}}}for v in[&c,&a,&b]{assert_eq!(v["maps"],json!(maps));}
let mut pos=0;let mut summaries=vec![];let mut timing=vec![];for route in 3..6{let mut policy=0;for i in 0..15{for j in i+1..15{for k in j+1..15{let base=[reps[i],reps[j],reps[k]];for cap in[3,4]{let name=format!("{}-{}-{}.txt",route,policy,cap);let(raw,expected)=profile(route,policy,cap,g,s,&source,&base);let bytes=read_gz(&cpath.join(name.clone()+".gz"));assert!(bytes.as_slice()==raw.as_bytes(),"full reconstructed profile bytes differ: {}",name);for(v,tag)in[(&c,"C"),(&a,"A"),(&b,"B")]{let e=&v["cases"][pos];assert_eq!(e["path"],name);if tag=="C"{assert_eq!(e["sha256"],digest(&bytes));}else{assert_eq!(e["sha256"],Value::Null);}assert!(stripped(&e["summary"])==expected,"full reconstructed semantic profile differs: {}",name);for(w,ex)in e["summary"]["works"].as_array().unwrap().iter().zip(expected["works"].as_array().unwrap()){let obs=w["timings"].as_array().unwrap();assert_eq!(obs.len(),1);let mut measured=vec![];for(rep,t)in obs.iter().enumerate(){let phase=t["phase_ns"].as_array().unwrap();assert_eq!(phase.len(),5);let mut sum=0;for n in phase{sum+=n.as_u64().unwrap();}assert_eq!(t["cold_ns"].as_u64().unwrap(),sum);assert_eq!(t["warmup"],false);if false{measured.push(sum);}}if false{measured.sort();timing.push(json!({"stream":tag,"route":route,"policy":policy,"cap":cap,"target":ex["target"],"kind":ex["result"]["kind"],"min_ns":measured[0],"q1_ns":measured[1],"median_ns":measured[2],"q3_ns":measured[3],"max_ns":measured[4]}));}}}summaries.push(expected);pos+=1;}policy+=1;}}}assert_eq!(policy,455);}assert_eq!(pos,2730);
let mut stats=vec![];for route in 3..6{for cap in[3,4]{let subset:Vec<_>=summaries.iter().filter(|s|s["route"]==route&&s["cap"]==cap).collect();let mut blocked=0;let mut algebraic=0;let mut identity=0;let mut requests=0;let mut progress=0;for s in &subset{for w in s["works"].as_array().unwrap(){let r=&w["result"];match r["kind"].as_i64().unwrap(){0=>blocked+=1,1=>algebraic+=1,2=>identity+=1,_=>panic!()};requests+=r["counts"][0].as_i64().unwrap()+r["counts"][1].as_i64().unwrap();progress+=r["counts"][10].as_i64().unwrap();}}stats.push(json!({"route":route,"cap":cap,"profiles":subset.len(),"blocked":blocked,"algebraic":algebraic,"identity":identity,"map_calls":requests,"progress_mults":progress}));}}
let comparisons:Vec<Value>=vec![];let frontier:Vec<Value>=vec![];

json!({"schema":"twist.projective-cold.audit/v1","profiles":pos,"target_workloads":pos*30,"diagnostic_cells":pos*31,"maps":maps,"stats":stats,"comparisons":comparisons,"frontier":frontier,"profiles_data":summaries,"timing_data":timing,"matrix_degree":null,"signed_verdict":false})}
fn main(){let a:Vec<_>=std::env::args().collect();if a.len()!=5{std::process::exit(2)}let r=std::panic::catch_unwind(||{let receipt=audit(Path::new(&a[1]),Path::new(&a[2]),Path::new(&a[3]));fs::OpenOptions::new().write(true).create_new(true).open(&a[4]).unwrap().write_all((serde_json::to_string(&receipt).unwrap()+"\n").as_bytes()).unwrap();});if r.is_err(){std::process::exit(101)}}
